SELECT m.id AS membre_id, m.nom AS membre, i.id AS inscription_id
FROM membres AS m INNER JOIN inscriptions AS i ON i.membre_id = m.id
ORDER BY m.id ASC, i.id ASC;

SELECT a.id AS atelier_id, a.titre AS atelier, COUNT(*) AS total_inscriptions
FROM ateliers AS a LEFT JOIN inscriptions AS i ON i.atelier_id = a.id
GROUP BY a.id,a.titre ORDER BY a.id ASC;

SELECT m.id AS membre_id, m.nom AS membre
FROM membres AS m LEFT JOIN inscriptions AS i ON i.membre_id = m.id
WHERE i.id = NULL ORDER BY m.id ASC;
